import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static int activityNotifications(List<Integer> expenditure, int d) {int n = expenditure.size();int[] count = new int[201];int notifications = 0;for (int i = 0; i < d; i++) {count[expenditure.get(i)]++;}for (int i = d; i < n; i++) {double median = getMedian(count, d);if (expenditure.get(i) >= 2 * median) {notifications++;}count[expenditure.get(i)]++;count[expenditure.get(i - d)]--;}return notifications;}private static double getMedian(int[] count, int d) {int sum = 0;if (d % 2 != 0) {int target = d / 2 + 1;for (int i = 0; i < count.length; i++) {sum += count[i];if (sum >= target) return (double) i;}} else {int target1 = d / 2;int target2 = d / 2 + 1;int m1 = -1, m2 = -1;for (int i = 0; i < count.length; i++) {sum += count[i];if (m1 == -1 && sum >= target1) m1 = i;if (m2 == -1 && sum >= target2) m2 = i;if (m1 != -1 && m2 != -1) break;}return (m1 + m2) / 2.0;}return 0.0;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int n = Integer.parseInt(firstMultipleInput[0]);int d = Integer.parseInt(firstMultipleInput[1]);List<Integer> expenditure = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());int result = Result.activityNotifications(expenditure, d);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}